"""Load and validate the YAML run specification (generated by scripts/euler.sh)."""

import copy
import os
import re

from omegaconf import OmegaConf

DEFAULTS = {
    "run": {
        "experiment": None,       # folder with the input files (required)
        "inputs": ["*.yaml"],     # glob patterns, relative to experiment, frozen into the run
        "scratch_root": "$SCRATCH",
        "data_dir": None,         # passed to plugins as context; never copied
        "project_dir": None,      # folder that makes euler_funs and user code importable (required)
    },
    "plugin": {
        "path": None,             # training | sweep | dagsweep | "module" | "module:attribute"
        "options": {},
    },
    "resources": {
        "walltime": "04:00:00",   # <= 4h places jobs in the 4h partition on Euler
        "signal_margin": 600,     # [s] before walltime at which USR1 asks tasks to pause
        "cpus_per_task": 1,
        "mem_per_cpu": "10g",
        "accelerator": "gpu",     # cpu | gpu
        "gpus": 1,
        "gpu_type": "",
        "gpu_mem": "",            # Euler gpumem, e.g. 24g
        "partition": "",
        "modules": ["stack/2024-06", "gcc/12.2.0", "python_cuda/3.11.6"],
        "setup": [],              # raw shell lines run before the worker (trusted input)
        "venv": None,
        "env": {},
        "extra_sbatch": [],       # e.g. ["--tmp=20g"]
    },
    "scheduling": {
        "schedule": "chain",      # single | chain
        "lanes": 6,               # maximum concurrent jobs
        "max_chunks": 40,         # allocations per lane, including the first
        "max_failures": 2,        # crashes/exceptions per task before FAILED
        "job_prefix": "ew",
    },
}

TOKEN = re.compile(r"[A-Za-z0-9_:.,/-]*")
SBATCH_OPTION = re.compile(r"--[a-z][a-z-]*(=[A-Za-z0-9_:.,=/@%+-]*)?")
PATH_KEYS = (("run", "experiment"), ("run", "scratch_root"), ("run", "data_dir"),
             ("run", "project_dir"), ("resources", "venv"))


def walltime_seconds(value):
    match = re.fullmatch(r"(?:(\d+)-)?(\d+):(\d{2}):(\d{2})", value)
    if not match:
        raise ValueError("walltime must be HH:MM:SS or D-HH:MM:SS")
    days, hours, minutes, seconds = (int(item or 0) for item in match.groups())
    return ((days * 24 + hours) * 60 + minutes) * 60 + seconds


def load_spec(path):
    """Merge a user YAML over DEFAULTS, expand paths, and validate."""
    user = OmegaConf.to_container(OmegaConf.load(path), resolve=True) or {}
    spec = {}
    for section, defaults in DEFAULTS.items():
        given = dict(user.pop(section, None) or {})
        unknown = set(given) - set(defaults)
        if unknown:
            raise ValueError(f"Unknown keys in {section}: {sorted(unknown)}")
        spec[section] = {**copy.deepcopy(defaults), **given}
    if user:
        raise ValueError(f"Unknown sections: {sorted(user)}")
    for section, key in PATH_KEYS:
        if spec[section][key]:
            spec[section][key] = os.path.expanduser(os.path.expandvars(str(spec[section][key])))
    validate(spec)
    return spec


def validate(spec):
    run, resources, scheduling = spec["run"], spec["resources"], spec["scheduling"]
    for key in ("experiment", "project_dir"):
        if not run[key]:
            raise ValueError(f"run.{key} is required")
    if "$" in run["scratch_root"]:
        raise ValueError("run.scratch_root contains an unset environment variable")
    if not spec["plugin"]["path"]:
        raise ValueError("plugin.path is required")
    for key in ("walltime", "mem_per_cpu", "gpu_type", "gpu_mem", "partition"):
        if not TOKEN.fullmatch(str(resources[key])):
            raise ValueError(f"Invalid resources.{key}: {resources[key]}")
    if resources["accelerator"] not in ("cpu", "gpu"):
        raise ValueError("resources.accelerator must be cpu or gpu")
    if not 0 < int(resources["signal_margin"]) < walltime_seconds(resources["walltime"]):
        raise ValueError("resources.signal_margin must be positive and shorter than walltime")
    for key in ("cpus_per_task", "gpus"):
        if int(resources[key]) < 1:
            raise ValueError(f"resources.{key} must be >= 1")
    for option in resources["extra_sbatch"]:
        if not SBATCH_OPTION.fullmatch(option):
            raise ValueError(f"Invalid extra_sbatch option: {option}")
        if option.split("=")[0] == "--mem":
            # Euler rejects per-node memory; see scripts/euler_instructions.txt.
            raise ValueError("--mem is not supported on Euler; use resources.mem_per_cpu")
    for key in resources["env"]:
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", key):
            raise ValueError(f"Invalid environment variable name: {key}")
    if scheduling["schedule"] not in ("single", "chain"):
        raise ValueError("scheduling.schedule must be single or chain")
    for key in ("lanes", "max_chunks", "max_failures"):
        if int(scheduling[key]) < 1:
            raise ValueError(f"scheduling.{key} must be >= 1")
    if not re.fullmatch(r"[A-Za-z0-9_]{1,16}", scheduling["job_prefix"]):
        raise ValueError("scheduling.job_prefix must be 1-16 alphanumeric characters")
